// Adjustable assumptions for the simulation; these are not live market quotations.
export const REALISM_DEFAULTS={demand:1,plaPrice:24,petgPrice:28,monthlyFixed:80,hourValue:15,supplierShipping:4.9,supplierHours:16,failureRate:1,maintenanceHours:200,amortizationYears:5,standbyW:0,auxiliaryW:0};
export const REALISM_LIMITS={demand:[.4,1.6],plaPrice:[10,80],petgPrice:[12,90],monthlyFixed:[0,1500],hourValue:[0,60],supplierShipping:[0,20],supplierHours:[8,120],failureRate:[.5,2],maintenanceHours:[80,400],amortizationYears:[3,10],standbyW:[0,20],auxiliaryW:[0,200]};
export const REALISM_PRESETS={balanced:{name:'Équilibré',note:'Le fonctionnement actuel, avec les machines en impression seules dans la facture.',...REALISM_DEFAULTS},realistic:{name:'Réaliste',note:'Ajoute la veille, le bureau et un approvisionnement un peu moins immédiat.',...REALISM_DEFAULTS,supplierHours:24,standbyW:5,auxiliaryW:40},careful:{name:'Exigeant',note:'Demande plus basse, achats plus chers et davantage d’entretien à anticiper.',...REALISM_DEFAULTS,demand:.75,plaPrice:30,petgPrice:34,monthlyFixed:160,hourValue:18,supplierShipping:6.9,supplierHours:48,failureRate:1.4,maintenanceHours:150,standbyW:8,auxiliaryW:60}};
export function normalizeRealism(input){const out={};for(const [k,fallback] of Object.entries(REALISM_DEFAULTS)){const value=input?.[k];out[k]=typeof value==='number'&&Number.isFinite(value)?Math.max(REALISM_LIMITS[k][0],Math.min(REALISM_LIMITS[k][1],value)):fallback;}return out;}
export const realismFor=s=>s.settings?.realism||REALISM_DEFAULTS;
export const materialPrice=(settings,material)=>settings?.realism?.[material+'Price']??REALISM_DEFAULTS[material+'Price'];
export function setRealism(s,values){if(!values||Object.entries(values).some(([k,v])=>!(k in REALISM_LIMITS)||!Number.isFinite(v)||v<REALISM_LIMITS[k][0]||v>REALISM_LIMITS[k][1]))return {ok:false,message:'Vérifie les valeurs : chaque réglage doit rester dans la plage indiquée.'};s.settings.realism=normalizeRealism({...realismFor(s),...values});return {ok:true};}
export function applyRealismPreset(s,id){const preset=REALISM_PRESETS[id];if(!preset)return {ok:false,message:'Profil inconnu.'};s.settings.realism=normalizeRealism(preset);return {ok:true};}
export function normalizePresentation(input){return {animation:['fluid','eco','instant'].includes(input?.animation)?input.animation:'fluid',simple:input?.simple!==false};}
